@DisplayName("HANDMADE 는 재고 관리 대상이 아니다")
@Test
void containsStockTypeHandmade() {
    ProductType type = ProductType.HANDMADE;

    boolean result = ProductType.containsStockType(type);

    assertThat(result).isFalse();
}

@DisplayName("BOTTLE 은 재고 관리 대상이다")
@Test
void containsStockTypeBottle() {
    ProductType type = ProductType.BOTTLE;

    boolean result = ProductType.containsStockType(type);

    assertThat(result).isTrue();
}

@DisplayName("BAKERY 는 재고 관리 대상이다")
@Test
void containsStockTypeBakery() {
    ProductType type = ProductType.BAKERY;

    boolean result = ProductType.containsStockType(type);

    assertThat(result).isTrue();
}

@DisplayName("상품 타입이 재고 관리 대상인지 확인한다")
@CsvSource({
        "HANDMADE, false",
        "BOTTLE, true",
        "BAKERY, true"
})
@ParameterizedTest
void containsStockType(ProductType productType, boolean expected) {
    // when
    boolean result = ProductType.containsStockType(productType);

    // then
    assertThat(result).isEqualTo(expected);
}

